ALTER TABLE "gate_results" ADD CONSTRAINT "gate_results_permission_resume_check" CHECK (("gate_results"."permission_resume" IS NULL AND "gate_results"."prompt_ordinal" = 0) OR (jsonb_typeof("gate_results"."permission_resume") = 'object' AND "gate_results"."permission_resume"->'version' = '1'::jsonb AND "gate_results"."kind" IN ('ai_judgment', 'skill_check') AND (("gate_results"."permission_resume"->>'kind' = 'permission' AND "gate_results"."prompt_ordinal" > 0) OR ("gate_results"."permission_resume"->>'kind' = 'permission_result' AND "gate_results"."prompt_ordinal" >= 0 AND jsonb_typeof("gate_results"."permission_resume"->'inputCommandId') = 'string' AND jsonb_typeof("gate_results"."permission_resume"->'checkpointCommandId') = 'string' AND "gate_results"."permission_resume"->>'verdictSha256' ~ '^[a-f0-9]{64}$')) AND "gate_results"."permission_resume"->'promptOrdinal' = to_jsonb("gate_results"."prompt_ordinal") AND "gate_results"."permission_resume"->>'parentActionSha256' ~ '^[a-f0-9]{64}$' AND jsonb_typeof("gate_results"."permission_resume"->'sourceCommandId') = 'string' AND jsonb_typeof("gate_results"."permission_resume"->'sourceAssignmentId') = 'string' AND jsonb_typeof("gate_results"."permission_resume"->'sourceIncarnationId') = 'string' AND jsonb_typeof("gate_results"."permission_resume"->'assignmentId') = 'string' AND jsonb_typeof("gate_results"."permission_resume"->'resumeSessionId') = 'string' AND jsonb_typeof("gate_results"."permission_resume"->'hitlRequestId') = 'string' AND jsonb_typeof("gate_results"."permission_resume"->'sourceRequestId') = 'string' AND jsonb_typeof("gate_results"."permission_resume"->'optionId') = 'string') IS TRUE);